export function validateCampaignSituations(chapterIds: readonly string[]) {
  const parsedSources = z.record(z.string(), sourceSchema).parse(sources);
  const parsedStages = z.array(situationSchema).parse(stages);
  const assigned = new Set<string>();
  for (const s of parsedStages) {
    if (s.sourceIds.some((id) => !parsedSources[id]))
      throw new Error(`战局来源缺失：${s.id}`);
    for (const id of s.chapterIds) {
      if (!chapterIds.includes(id) || assigned.has(id))
        throw new Error(`战局章节重复或失效：${id}`);
      assigned.add(id);
    }
  }
  if (chapterIds.some((id) => !assigned.has(id)))
    throw new Error('战局研究尚未覆盖全部章节');
  return {
    sources: parsedSources,
    stages: parsedStages,
    spatialPrecision: 'schematic' as const,
    reviewStatus: 'draft' as const,
    releaseStatus: 'unpublished' as const,
    reviews: [],
  };
}
export type CampaignResearch = ReturnType<typeof validateCampaignSituations>;
export type CampaignSituation = CampaignResearch['stages'][number];
